#include<bits/stdc++.h>
#define int long long
using namespace std;
char a[555][555];
struct node{
	int x,y;
};
int n,m;
vector<node>v;
int dp[555][555];
int ans[555][555];
int dfs(int p,int k){
//	cout<<p<<" "<<k?<<endl;
	if(k==0||p==v.size()){
		memset(dp,0,sizeof(dp));
		for(int i=1;i<=n;i++){
			for(int j=1;j<=m;j++){
//				cout<<(int)(a[i][j]-'0')<<" "; 
				if(a[i][j]=='?'){
					a[i][j]='0';
				}
				dp[i][j]=max(dp[i][j-1],dp[i-1][j])+(int)(a[i][j]-'0');
			}
//			cout<<endl;
		}
		return dp[n][m];
	}if(ans[p][k]!=-1){
		return ans[p][k];
	}else{
		int x=0;
		if(k>0){
			a[v[p].x][v[p].y]='1';
			x=dfs(p+1,k-1);
			a[v[p].x][v[p].y]='?';
		}
		a[v[p].x][v[p].y]='0';
		x=max(x,dfs(p+1,k));
		a[v[p].x][v[p].y]='?';
		ans[p][k]=x;
		return x;
	}
}
void pig(){
	int k;
	cin>>n>>m>>k;
	v.clear();
	memset(ans,-1,sizeof(ans));
	for(int i=1;i<=n;i++){
		for(int j=1;j<=m;j++){
			cin>>a[i][j];
			if(a[i][j]=='?'){
				v.push_back({i,j});
			}
		}
	}
	cout<<dfs(0,k)<<endl;
}
signed main(){
    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int t;
	cin>>t;
	while(t--){
		pig();
	}
    return 0;
}
